text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="description" content="Dune Line — the overnight train from the open desert to the neon city of Nocturne.">
  <meta name="theme-color" content="#141018">
  <title>Dune Line — Leave at dusk. Wake in neon.</title>
  <style>
    :root {
      --night: #141018;
      --night-raised: #201a26;
      --night-line: #39313f;
      --paper: #f3efe7;
      --paper-deep: #e8e0d5;
      --ink: #211a24;
      --muted: #736b74;
      --sand: #d8b286;
      --ember: #ed9a73;
      --copper: #a65338;
      --lilac: #c6afff;
      --white: #fffaf2;
      --serif: "Iowan Old Style", "Baskerville", "Times New Roman", Georgia, serif;
      --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
    }

    *, *::before, *::after {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      background: var(--night);
      color: var(--white);
      font-family: var(--sans);
      font-size: 16px;
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    ::selection {
      color: var(--night);
      background: var(--ember);
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button, a {
      -webkit-tap-highlight-color: transparent;
    }

    button {
      font: inherit;
    }

    img, svg {
      display: block;
    }

    h1, h2, h3, p, figure, blockquote {
      margin: 0;
    }

    ul {
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .shell {
      width: min(1184px, calc(100% - 96px));
      margin-inline: auto;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .skip-link {
      position: fixed;
      top: 12px;
      left: 12px;
      z-index: 1000;
      padding: 12px 18px;
      color: var(--night);
      background: var(--white);
      transform: translateY(-160%);
      transition: transform 180ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    :focus-visible {
      outline: 2px solid var(--ember);
      outline-offset: 5px;
    }

    #experience, #timetable, #fares {
      scroll-margin-top: 20px;
    }

    /* Header */
    .site-header {
      position: relative;
      z-index: 20;
      background: var(--night);
      border-bottom: 1px solid rgba(255, 255, 255, 0.11);
    }

    .header-inner {
      position: relative;
      min-height: 84px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 40px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      flex: 0 0 auto;
    }

    .brand-mark {
      width: 35px;
      height: 35px;
      color: var(--ember);
    }

    .brand-name {
      font-size: 14px;
      line-height: 1;
      font-weight: 700;
      letter-spacing: 0.18em;
    }

    .brand-name span {
      font-weight: 400;
    }

    .brand-edition {
      margin-left: 4px;
      padding-left: 16px;
      border-left: 1px solid var(--night-line);
      color: #948b99;
      font-size: 9px;
      line-height: 1.35;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    .main-nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .main-nav > a:not(.nav-cta) {
      position: relative;
      color: #c2bbc6;
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.04em;
      transition: color 180ms ease;
    }

    .main-nav > a:not(.nav-cta)::after {
      content: "";
      position: absolute;
      right: 0;
      bottom: -8px;
      left: 0;
      height: 1px;
      background: var(--ember);
      transform: scaleX(0);
      transform-origin: right;
      transition: transform 180ms ease;
    }

    .main-nav > a:not(.nav-cta):hover {
      color: var(--white);
    }

    .main-nav > a:not(.nav-cta):hover::after {
      transform: scaleX(1);
      transform-origin: left;
    }

    .nav-cta {
      display: inline-flex;
      align-items: center;
      gap: 22px;
      min-height: 42px;
      padding: 0 17px;
      border: 1px solid #625768;
      color: var(--white);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      transition: background 180ms ease, border-color 180ms ease;
    }

    .nav-cta:hover {
      background: rgba(255, 255, 255, 0.07);
      border-color: var(--ember);
    }

    .menu-toggle {
      display: none;
      width: 44px;
      height: 44px;
      padding: 0;
      border: 1px solid var(--night-line);
      color: var(--white);
      background: transparent;
      cursor: pointer;
    }

    .menu-toggle span {
      display: block;
      width: 18px;
      height: 1px;
      margin: 5px auto;
      background: currentColor;
      transition: transform 180ms ease;
    }

    .menu-toggle[aria-expanded="true"] span:first-child {
      transform: translateY(3px) rotate(45deg);
    }

    .menu-toggle[aria-expanded="true"] span:last-child {
      transform: translateY(-3px) rotate(-45deg);
    }

    /* Hero */
    .hero {
      position: relative;
      overflow: hidden;
      padding: 60px 0 62px;
      background:
        radial-gradient(circle at 86% 12%, rgba(114, 78, 139, 0.13), transparent 29%),
        var(--night);
    }

    .hero-top {
      display: grid;
      grid-template-columns: minmax(0, 1.55fr) minmax(300px, 0.65fr);
      gap: 80px;
      align-items: end;
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 12px;
      color: var(--copper);
      font-size: 10px;
      line-height: 1.4;
      font-weight: 700;
      letter-spacing: 0.2em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 28px;
      height: 1px;
      flex: 0 0 auto;
      background: currentColor;
    }

    .hero .eyebrow {
      margin-bottom: 24px;
      color: var(--ember);
    }

    .hero h1 {
      max-width: 790px;
      font-family: var(--serif);
      font-size: clamp(66px, 7.15vw, 92px);
      line-height: 0.96;
      font-weight: 400;
      letter-spacing: -0.055em;
    }

    .hero h1 em {
      color: var(--lilac);
      font-weight: 400;
    }

    .hero-intro {
      padding-bottom: 4px;
    }

    .journey-code {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 20px;
      color: #e5dce8;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .journey-code .arrow {
      color: var(--ember);
      font-size: 17px;
      font-weight: 400;
    }

    .hero-description {
      max-width: 400px;
      color: #b8afbd;
      font-size: 16px;
      line-height: 1.7;
    }

    .hero-actions {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 24px;
      margin-top: 26px;
    }

    .button-primary {
      display: inline-flex;
      align-items: center;
      justify-content: space-between;
      gap: 28px;
      min-height: 50px;
      padding: 0 20px;
      color: #211720;
      background: var(--ember);
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.025em;
      transition: background 180ms ease, transform 180ms ease;
    }

    .button-primary:hover {
      background: #ffb18c;
      transform: translateY(-2px);
    }

    .text-link {
      display: inline-flex;
      align-items: center;
      gap: 9px;
      padding: 8px 0;
      color: #d3cbd7;
      border-bottom: 1px solid #514654;
      font-size: 12px;
      transition: border-color 180ms ease, color 180ms ease;
    }

    .text-link:hover {
      color: var(--white);
      border-color: var(--ember);
    }

    .hero-price-note {
      margin-top: 17px;
      color: #857c8a;
      font-size: 10px;
      letter-spacing: 0.055em;
    }

    .hero-visual {
      position: relative;
      aspect-ratio: 1200 / 440;
      margin-top: 52px;
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.13);
      border-radius: 3px;
      background: #191421;
    }

    .hero-art {
      width: 100%;
      height: 100%;
    }

    .art-label {
      position: absolute;
      z-index: 2;
      top: 22px;
      display: flex;
      align-items: center;
      gap: 8px;
      color: rgba(255, 250, 242, 0.75);
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      pointer-events: none;
    }

    .art-label.left {
      left: 24px;
    }

    .art-label.right {
      right: 24px;
      color: rgba(222, 211, 234, 0.66);
    }

    .live-dot {
      width: 5px;
      height: 5px;
      border-radius: 50%;
      background: var(--ember);
      box-shadow: 0 0 0 4px rgba(237, 154, 115, 0.12);
    }

    .crossing-label {
      position: absolute;
      bottom: 20px;
      left: 22px;
      z-index: 2;
      padding: 10px 13px;
      border: 1px solid rgba(255, 255, 255, 0.14);
      background: rgba(20, 16, 24, 0.57);
      backdrop-filter: blur(8px);
      pointer-events: none;
    }

    .crossing-label small {
      display: block;
      margin-bottom: 3px;
      color: #a69aa9;
      font-size: 8px;
      font-weight: 700;
      letter-spacing: 0.17em;
      text-transform: uppercase;
    }

    .crossing-label span {
      color: #f4e9df;
      font-family: var(--serif);
      font-size: 17px;
      letter-spacing: 0.02em;
    }

    .art-coordinate {
      position: absolute;
      right: 24px;
      bottom: 23px;
      z-index: 2;
      color: rgba(241, 224, 213, 0.48);
      font-size: 8px;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      pointer-events: none;
    }

    /* Shared section headings */
    .section-heading {
      display: grid;
      grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.55fr);
      gap: 80px;
      align-items: end;
    }

    .section-heading .eyebrow {
      margin-bottom: 20px;
    }

    .section-heading h2 {
      max-width: 720px;
      font-family: var(--serif);
      font-size: clamp(43px, 4.6vw, 60px);
      line-height: 1.03;
      font-weight: 400;
      letter-spacing: -0.04em;
    }

    .section-heading > p {
      max-width: 390px;
      padding-bottom: 4px;
      color: var(--muted);
      font-size: 15px;
      line-height: 1.75;
    }

    /* Experience */
    .experience {
      padding: 110px 0 112px;
      color: var(--ink);
      background: var(--paper);
    }

    .feature-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 48px;
      margin-top: 76px;
    }

    .feature {
      padding-top: 22px;
      border-top: 1px solid #cec5b9;
    }

    .feature-top {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      min-height: 100px;
    }

    .feature-number {
      padding-top: 5px;
      color: #8d8189;
      font-family: var(--serif);
      font-size: 13px;
      font-style: italic;
    }

    .feature-icon {
      width: 93px;
      height: 93px;
      color: #7f493d;
    }

    .feature h3 {
      margin-top: 29px;
      font-family: var(--serif);
      font-size: 27px;
      line-height: 1.15;
      font-weight: 400;
      letter-spacing: -0.025em;
    }

    .feature p {
      max-width: 330px;
      margin-top: 15px;
      color: var(--muted);
      font-size: 14px;
      line-height: 1.75;
    }

    /* Timetable */
    .timetable-wrap {
      margin-top: 106px;
      padding-top: 78px;
      border-top: 1px solid #d2c8bc;
    }

    .timetable-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 40px;
    }

    .timetable-heading .eyebrow {
      margin-bottom: 17px;
    }

    .timetable-heading h2 {
      font-family: var(--serif);
      font-size: clamp(42px, 4.2vw, 56px);
      line-height: 1;
      font-weight: 400;
      letter-spacing: -0.04em;
    }

    .route-note {
      padding-bottom: 4px;
      text-align: right;
    }

    .route-note strong {
      display: block;
      color: #473b45;
      font-size: 10px;
      letter-spacing: 0.13em;
      text-transform: uppercase;
    }

    .route-note span {
      display: block;
      margin-top: 6px;
      color: #867b83;
      font-size: 11px;
    }

    .schedule {
      width: 100%;
      margin-top: 45px;
      border-collapse: collapse;
      table-layout: fixed;
    }

    .schedule th {
      padding: 0 12px 15px;
      color: #8b7f86;
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 0.15em;
      text-align: left;
      text-transform: uppercase;
    }

    .schedule th:first-child,
    .schedule td:first-child {
      padding-left: 0;
    }

    .schedule th:nth-child(1) { width: 17%; }
    .schedule th:nth-child(2) { width: 20%; }
    .schedule th:nth-child(3) { width: 20%; }
    .schedule th:nth-child(4) { width: 12%; }
    .schedule th:nth-child(5) { width: 23%; }
    .schedule th:nth-child(6) { width: 8%; }

    .schedule tbody tr {
      border-top: 1px solid #d6cdc1;
      transition: background 180ms ease;
    }

    .schedule tbody tr:last-child {
      border-bottom: 1px solid #d6cdc1;
    }

    .schedule td {
      padding: 23px 12px;
      vertical-align: middle;
    }

    .service-name strong {
      display: block;
      color: #2b212b;
      font-size: 12px;
      letter-spacing: 0.11em;
    }

    .service-name span {
      display: block;
      margin-top: 4px;
      color: #8a7d84;
      font-family: var(--serif);
      font-size: 14px;
      font-style: italic;
    }

    .time-cell time {
      display: block;
      color: #2b212b;
      font-family: var(--serif);
      font-size: 28px;
      line-height: 1;
      font-variant-numeric: tabular-nums;
      letter-spacing: -0.02em;
    }

    .time-cell span {
      display: block;
      margin-top: 7px;
      color: #877b82;
      font-size: 10px;
    }

    .duration {
      color: #5f535b;
      font-size: 12px;
      font-variant-numeric: tabular-nums;
    }

    .availability {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: #5a5057;
      font-size: 11px;
      white-space: nowrap;
    }

    .availability::before {
      content: "";
      width: 6px;
      height: 6px;
      flex: 0 0 auto;
      border-radius: 50%;
      background: #56836b;
    }

    .availability.limited::before {
      background: #c57445;
    }

    .row-action {
      text-align: right;
    }

    .row-action a {
      display: inline-grid;
      width: 42px;
      height: 42px;
      place-items: center;
      border: 1px solid #bfb3a9;
      border-radius: 50%;
      color: #493a43;
      transition: color 180ms ease, background 180ms ease, border-color 180ms ease;
    }

    .row-action a:hover {
      color: var(--paper);
      background: var(--ink);
      border-color: var(--ink);
    }

    .schedule-note {
      margin-top: 18px;
      color: #8a7e85;
      font-size: 10px;
      line-height: 1.6;
    }

    /* Fares */
    .fares {
      padding: 112px 0 120px;
      background:
        radial-gradient(circle at 80% 2%, rgba(133, 95, 158, 0.12), transparent 30%),
        var(--night);
    }

    .fares .eyebrow {
      color: var(--ember);
    }

    .fares .section-heading > p {
      color: #a99fac;
    }

    .fare-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
      align-items: stretch;
      margin-top: 76px;
    }

    .fare-card {
      position: relative;
      display: flex;
      min-height: 514px;
      flex-direction: column;
      padding: 32px;
      border: 1px solid var(--night-line);
      background: rgba(255, 255, 255, 0.018);
    }

    .fare-card.featured {
      top: -14px;
      min-height: 542px;
      color: var(--ink);
      background: var(--paper);
      border-color: var(--paper);
    }

    .popular-badge {
      position: absolute;
      top: 28px;
      right: 28px;
      padding: 6px 9px;
      color: #653728;
      background: #ecc2a4;
      font-size: 8px;
      font-weight: 800;
      letter-spacing: 0.13em;
      text-transform: uppercase;
    }

    .fare-kicker {
      color: #a99eab;
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    .featured .fare-kicker {
      color: #8c7470;
    }

    .fare-card h3 {
      margin-top: 15px;
      font-family: var(--serif);
      font-size: 28px;
      line-height: 1.1;
      font-weight: 400;
      letter-spacing: -0.025em;
    }

    .fare-description {
      min-height: 47px;
      margin-top: 12px;
      color: #aaa0ad;
      font-size: 13px;
      line-height: 1.65;
    }

    .featured .fare-description {
      color: #756a72;
    }

    .price {
      display: flex;
      align-items: baseline;
      gap: 9px;
      margin-top: 27px;
      padding-bottom: 26px;
      border-bottom: 1px solid var(--night-line);
    }

    .featured .price {
      border-color: #d1c6b9;
    }

    .price strong {
      font-family: var(--serif);
      font-size: 54px;
      line-height: 1;
      font-weight: 400;
      letter-spacing: -0.045em;
    }

    .price span {
      color: #948994;
      font-size: 10px;
      line-height: 1.4;
    }

    .featured .price span {
      color: #786c72;
    }

    .fare-list {
      display: grid;
      gap: 13px;
      margin: 26px 0 30px;
      color: #c1b8c4;
      font-size: 12px;
    }

    .featured .fare-list {
      color: #564a53;
    }

    .fare-list li {
      position: relative;
      padding-left: 20px;
    }

    .fare-list li::before {
      content: "";
      position: absolute;
      top: 0.55em;
      left: 1px;
      width: 8px;
      height: 4px;
      border-bottom: 1px solid var(--ember);
      border-left: 1px solid var(--ember);
      transform: rotate(-45deg);
    }

    .featured .fare-list li::before {
      border-color: var(--copper);
    }

    .fare-button {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 49px;
      margin-top: auto;
      padding: 0 17px;
      border: 1px solid #5b4e60;
      color: #efe7ee;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.04em;
      transition: color 180ms ease, background 180ms ease, border-color 180ms ease;
    }

    .fare-button:hover {
      color: var(--night);
      background: var(--ember);
      border-color: var(--ember);
    }

    .featured .fare-button {
      color: var(--paper);
      background: var(--ink);
      border-color: var(--ink);
    }

    .featured .fare-button:hover {
      color: var(--ink);
      background: var(--ember);
      border-color: var(--ember);
    }

    .fares-footnote {
      margin-top: 22px;
      color: #7f7483;
      font-size: 10px;
      text-align: center;
      letter-spacing: 0.025em;
    }

    /* Testimonial */
    .testimonial {
      padding: 91px 0 94px;
      color: #2d1d24;
      background: #d88967;
    }

    .testimonial-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 176px;
      gap: 82px;
      align-items: center;
    }

    .testimonial .eyebrow {
      margin-bottom: 27px;
      color: #62352f;
    }

    blockquote {
      position: relative;
    }

    blockquote p {
      max-width: 900px;
      font-family: var(--serif);
      font-size: clamp(34px, 3.75vw, 48px);
      line-height: 1.16;
      letter-spacing: -0.035em;
    }

    blockquote footer {
      display: flex;
      align-items: center;
      gap: 14px;
      margin-top: 31px;
      font-size: 11px;
    }

    blockquote footer strong {
      font-weight: 700;
      letter-spacing: 0.04em;
    }

    blockquote footer span {
      padding-left: 14px;
      border-left: 1px solid rgba(45, 29, 36, 0.3);
      color: #6f4844;
    }

    .postmark {
      display: flex;
      width: 168px;
      aspect-ratio: 1;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      border: 1px solid rgba(45, 29, 36, 0.52);
      border-radius: 50%;
      transform: rotate(7deg);
    }

    .postmark::before {
      content: "";
      position: absolute;
      width: 148px;
      aspect-ratio: 1;
      border: 1px dashed rgba(45, 29, 36, 0.34);
      border-radius: 50%;
    }

    .postmark svg {
      width: 60px;
      height: 42px;
      margin-bottom: 8px;
    }

    .postmark strong {
      font-size: 10px;
      letter-spacing: 0.2em;
    }

    .postmark small {
      margin-top: 5px;
      font-size: 7px;
      letter-spacing: 0.13em;
      text-transform: uppercase;
    }

    /* Footer */
    .site-footer {
      padding: 72px 0 34px;
      background: #100d14;
    }

    .footer-top {
      display: grid;
      grid-template-columns: 1fr 1fr auto;
      gap: 60px;
      align-items: center;
    }

    .footer-tagline {
      max-width: 330px;
      color: #958b99;
      font-family: var(--serif);
      font-size: 20px;
      line-height: 1.4;
    }

    .footer-cta {
      display: inline-flex;
      align-items: center;
      gap: 28px;
      padding-bottom: 8px;
      border-bottom: 1px solid #66586b;
      color: var(--ember);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.07em;
      text-transform: uppercase;
      transition: border-color 180ms ease;
    }

    .footer-cta:hover {
      border-color: var(--ember);
    }

    .footer-route {
      display: flex;
      align-items: center;
      gap: 22px;
      margin: 64px 0 52px;
    }

    .station {
      flex: 0 0 auto;
    }

    .station strong {
      display: block;
      color: #ddd4df;
      font-size: 10px;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .station small {
      display: block;
      margin-top: 5px;
      color: #6f6574;
      font-size: 9px;
    }

    .station.arrival {
      text-align: right;
    }

    .route-line {
      position: relative;
      height: 1px;
      flex: 1;
      background: #3e3444;
    }

    .route-line::before,
    .route-line::after {
      content: "";
      position: absolute;
      top: -3px;
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: var(--ember);
    }

    .route-line::before { left: 0; }
    .route-line::after { right: 0; background: var(--lilac); }

    .route-line svg {
      position: absolute;
      top: -13px;
      left: 50%;
      width: 45px;
      height: 27px;
      padding: 3px;
      color: #8d7f91;
      background: #100d14;
      transform: translateX(-50%);
    }

    .footer-bottom {
      display: grid;
      grid-template-columns: 1fr 1fr auto;
      gap: 30px;
      align-items: center;
      padding-top: 25px;
      border-top: 1px solid #2e2733;
      color: #6f6574;
      font-size: 9px;
      letter-spacing: 0.035em;
    }

    .footer-bottom span:nth-child(2) {
      text-align: center;
    }

    .back-to-top {
      color: #a69aa9;
      transition: color 180ms ease;
    }

    .back-to-top:hover {
      color: var(--white);
    }

    /* Responsive */
    @media (min-width: 901px) {
      .schedule tbody tr:hover {
        background: rgba(255, 255, 255, 0.45);
      }
    }

    @media (max-width: 1050px) {
      .hero-top,
      .section-heading {
        gap: 50px;
      }

      .brand-edition {
        display: none;
      }

      .main-nav {
        gap: 24px;
      }

      .feature-grid {
        gap: 30px;
      }

      .fare-card {
        padding: 27px;
      }

      .popular-badge {
        top: 24px;
        right: 22px;
      }
    }

    @media (max-width: 900px) {
      .shell {
        width: calc(100% - 56px);
      }

      .menu-toggle {
        display: block;
      }

      .main-nav {
        position: absolute;
        top: calc(100% - 1px);
        right: 0;
        left: 0;
        display: none;
        align-items: stretch;
        flex-direction: column;
        gap: 0;
        padding: 18px 24px 26px;
        border: 1px solid var(--night-line);
        background: #1a151f;
        box-shadow: 0 24px 45px rgba(0, 0, 0, 0.3);
      }

      .main-nav.is-open {
        display: flex;
      }

      .main-nav > a:not(.nav-cta) {
        padding: 16px 0;
        border-bottom: 1px solid #332a39;
        font-family: var(--serif);
        font-size: 23px;
        font-weight: 400;
        letter-spacing: 0;
      }

      .main-nav > a:not(.nav-cta)::after {
        display: none;
      }

      .nav-cta {
        justify-content: space-between;
        margin-top: 20px;
      }

      .hero-top {
        grid-template-columns: 1fr;
        gap: 35px;
      }

      .hero-intro {
        display: grid;
        grid-template-columns: 1fr 1fr;
        column-gap: 36px;
      }

      .journey-code,
      .hero-description {
        grid-column: 1;
      }

      .hero-actions,
      .hero-price-note {
        grid-column: 2;
      }

      .hero-actions {
        grid-row: 1 / span 2;
        align-self: center;
        align-items: flex-start;
        flex-direction: column;
        margin-top: 0;
      }

      .hero-price-note {
        margin-top: -13px;
      }

      .section-heading {
        grid-template-columns: 1fr;
        gap: 26px;
      }

      .section-heading > p {
        max-width: 560px;
      }

      .feature h3 {
        font-size: 24px;
      }

      .schedule th:nth-child(4),
      .schedule td.duration {
        display: none;
      }

      .schedule th:nth-child(5) { width: 26%; }
      .schedule th:nth-child(6) { width: 5%; }

      .fare-grid {
        grid-template-columns: 1fr;
        gap: 16px;
        margin-top: 50px;
      }

      .fare-card,
      .fare-card.featured {
        top: 0;
        min-height: 0;
      }

      .fare-description {
        min-height: 0;
      }

      .fare-button {
        margin-top: 6px;
      }

      .fares-footnote {
        margin-top: 28px;
      }
    }

    @media (max-width: 700px) {
      .hero {
        padding-top: 46px;
      }

      .hero h1 {
        font-size: clamp(54px, 13.7vw, 78px);
      }

      .hero-visual {
        height: 390px;
        aspect-ratio: auto;
      }

      .hero-art {
        position: absolute;
        top: 0;
        right: 0;
        width: 1064px;
        max-width: none;
      }

      .art-label.right,
      .art-coordinate {
        display: none;
      }

      .feature-grid {
        grid-template-columns: 1fr;
        gap: 48px;
        margin-top: 54px;
      }

      .feature {
        display: grid;
        grid-template-columns: 94px 1fr;
        column-gap: 26px;
      }

      .feature-top {
        grid-row: 1 / span 2;
        min-height: 0;
      }

      .feature-number {
        display: none;
      }

      .feature h3,
      .feature p {
        margin-top: 0;
      }

      .feature p {
        margin-top: 12px;
      }

      .timetable-wrap {
        margin-top: 80px;
        padding-top: 60px;
      }

      .timetable-heading {
        align-items: flex-start;
        flex-direction: column;
        gap: 22px;
      }

      .route-note {
        text-align: left;
      }

      .schedule,
      .schedule tbody {
        display: block;
      }

      .schedule thead {
        display: none;
      }

      .schedule tbody tr {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 24px 20px;
        padding: 26px 0;
      }

      .schedule td,
      .schedule td:first-child {
        display: block;
        padding: 0;
      }

      .schedule td::before {
        content: attr(data-label);
        display: block;
        margin-bottom: 8px;
        color: #8b7f86;
        font-size: 8px;
        font-weight: 700;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      .schedule td.duration {
        display: block;
      }

      .schedule td.row-action {
        grid-column: 1 / -1;
        text-align: left;
      }

      .schedule td.row-action::before {
        display: none;
      }

      .row-action a {
        display: flex;
        width: 100%;
        height: 44px;
        align-items: center;
        justify-content: space-between;
        padding: 0 15px;
        border-radius: 0;
      }

      .row-action a::after {
        content: "View fares";
        order: -1;
        font-size: 10px;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      .testimonial-grid {
        grid-template-columns: 1fr;
        gap: 46px;
      }

      .postmark {
        width: 140px;
        justify-self: end;
      }

      .postmark::before {
        width: 122px;
      }

      .footer-top {
        grid-template-columns: 1fr;
        gap: 28px;
      }

      .footer-cta {
        justify-self: start;
      }

      .footer-bottom {
        grid-template-columns: 1fr auto;
        row-gap: 13px;
      }

      .footer-bottom span:nth-child(2) {
        grid-column: 1 / -1;
        grid-row: 2;
        text-align: left;
      }
    }

    @media (max-width: 520px) {
      .shell {
        width: calc(100% - 40px);
      }

      .header-inner {
        min-height: 74px;
      }

      .hero {
        padding-bottom: 42px;
      }

      .hero h1 {
        letter-spacing: -0.06em;
      }

      .hero-intro {
        display: block;
      }

      .hero-description {
        font-size: 15px;
      }

      .hero-actions {
        align-items: center;
        flex-direction: row;
        gap: 20px;
        margin-top: 24px;
      }

      .hero-price-note {
        margin-top: 15px;
      }

      .hero-visual {
        height: 350px;
        margin-top: 40px;
      }

      .crossing-label {
        bottom: 16px;
        left: 16px;
      }

      .art-label.left {
        top: 17px;
        left: 17px;
      }

      .experience,
      .fares {
        padding: 80px 0;
      }

      .section-heading h2,
      .timetable-heading h2 {
        font-size: 43px;
      }

      .feature {
        grid-template-columns: 72px 1fr;
        column-gap: 20px;
      }

      .feature-icon {
        width: 72px;
        height: 72px;
      }

      .feature h3 {
        font-size: 23px;
      }

      .schedule {
        margin-top: 35px;
      }

      .time-cell time {
        font-size: 26px;
      }

      .fare-card {
        padding: 27px 24px;
      }

      .popular-badge {
        position: static;
        align-self: flex-start;
        margin-bottom: 17px;
      }

      .testimonial {
        padding: 75px 0;
      }

      blockquote p {
        font-size: 34px;
      }

      blockquote footer {
        align-items: flex-start;
        flex-direction: column;
        gap: 7px;
      }

      blockquote footer span {
        padding-left: 0;
        border-left: 0;
      }

      .site-footer {
        padding-top: 55px;
      }

      .footer-route {
        gap: 12px;
        margin: 48px 0 40px;
      }

      .station strong {
        font-size: 8px;
      }

      .station small {
        font-size: 8px;
      }

      .route-line svg {
        display: none;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *, *::before, *::after {
        transition: none !important;
        animation: none !important;
      }
    }
  </style>
</head>
